import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.BVA38fkC.js";var i=JSON.parse(`{"title":"Project overview","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/docs/overview.html"}],["meta",{"property":"og:title","content":"Project overview | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/docs/overview.html"}],["meta",{"name":"twitter:title","content":"Project overview | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":1794147699000}`),a={name:`overview.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="project-overview" tabindex="-1">Project overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to “Project overview”">​</a></h1><p>FD Cal is a fixed-deposit planning and simulation tool. It models bank FD products, account constraints, interest, AIT, transfer fees, cash flows and maturity events to compare investment plans over a configured horizon.</p><h2 id="applications" tabindex="-1">Applications <a class="header-anchor" href="#applications" aria-label="Permalink to “Applications”">​</a></h2><table tabindex="0"><thead><tr><th>Application</th><th>Purpose</th><th>Available strategies</th></tr></thead><tbody><tr><td>Web application</td><td>Configure scenarios and inspect interactive results</td><td>Greedy, Absolute R+, GSS</td></tr><tr><td>Node.js CLI</td><td>Run scenarios, diagnostics and regression workflows</td><td>Greedy, Absolute R+, GSS, Absolute R</td></tr></tbody></table><p>Both applications use the same JavaScript calculation engine. The browser and CLI are runtime adapters; they must not implement separate financial or strategy logic. In the web app, CPU-intensive simulations run in a native ES-module Web Worker so the main thread can continue handling interaction and rendering.</p><h2 id="main-areas-of-the-repository" tabindex="-1">Main areas of the repository <a class="header-anchor" href="#main-areas-of-the-repository" aria-label="Permalink to “Main areas of the repository”">​</a></h2><ul><li><code>src/core/</code> — financial domain, immutable simulation context, authoritative runtime/state, event progression and result finalization.</li><li><code>src/strategies/</code> — session-based investment decisions, hypothetical planning and shared search algorithms.</li><li><code>src/fd-options/</code> — FD candidate discovery, eligibility and ordering.</li><li><code>src/reporting/</code> — shared result formatting and standalone HTML reports.</li><li><code>src/io/</code> — CSV parsing and Node-side data loading.</li><li><code>src/web/</code> — browser application.</li><li><code>src/cli/</code> — command-line application.</li><li><code>data/</code> and <code>schema/</code> — bank/product data and configuration contract.</li><li><code>tests/</code> — automated regression and contract tests.</li></ul><h2 id="important-boundaries" tabindex="-1">Important boundaries <a class="header-anchor" href="#important-boundaries" aria-label="Permalink to “Important boundaries”">​</a></h2><ul><li>Production strategies expose <code>createSession(context)</code> and return immutable decisions; they do not execute the authoritative simulation.</li><li><code>SimulationRuntime</code> owns actual event progression, outflow settlement, transfers, bookings and result construction. <code>SimulationEngine</code> owns session driving and exactly-once finalisation.</li><li>FDOptionManager owns FD candidate eligibility and ordering. Strategies consume its ordered candidates.</li><li>The final consolidation sweep belongs to the shared simulation lifecycle, not an individual strategy.</li><li>The <code>archive/</code> directory preserves the legacy Python project and should not be changed during normal JavaScript development.</li></ul><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further reading”">​</a></h2><ul><li><a href="/FD-Calculator/docs/guide/getting-started.html">Getting started</a></li><li><a href="/FD-Calculator/docs/STRATEGIES.html">Strategy comparison</a></li><li><a href="/FD-Calculator/docs/SIMULATION-LIFECYCLE.html">Simulation lifecycle</a></li><li><a href="/FD-Calculator/docs/reference/CODEBASE.html">Codebase map</a></li><li><a href="/FD-Calculator/docs/MIGRATION_PLAN.html">Migration plan</a></li><li><a href="/FD-Calculator/docs/guide/contributing.html">Contributor guide</a></li></ul>`,11)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};